CSS='''body{margin:0;background:#f2f5f9;color:#193047;font:16px/1.55 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:24px}article,.intro{background:white;padding:20px;border:1px solid #d5dfea;border-radius:12px;margin:17px 0}.valid{border-left:7px solid #27946b}.minor{border-left:7px solid #d69b2d}.context{border-left:7px solid #4a83b5}h1{font-size:1.85rem;line-height:1.2}h2{font-size:1.25rem}h3{font-size:1.03rem}.badge{font-size:.78rem;font-weight:750;padding:4px 9px;background:#edf3f7;border-radius:5px}.eq{background:#f1f5fa;padding:12px 15px;margin:12px 0;border-radius:7px;font:1.02em/1.85 Cambria,'DejaVu Serif',serif;overflow-x:auto}.muted,small{color:#53697d;font-size:.88rem}a{color:#185ca0}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #d8e1ec;padding:10px;text-align:left;vertical-align:top}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.tile{padding:12px;background:#edf4f8;border-radius:6px}details{padding-top:9px}summary{font-weight:650;cursor:pointer}li{margin:7px 0}code{font-size:.86em}@media(max-width:600px){main{padding:11px}article,.intro{padding:14px}.eq{font-size:.93em}table{font-size:.86em}}'''
